@@ -54,35 +54,25 @@ export function evaluateSpokenExpression(source: string): number {
     const numberWord = NUMBER_WORDS[word];
     if (numberWord !== undefined) return numberWord;

-    // Operators are prefix forms. Each branch repeats the same parser work on
-    // purpose, leaving several safe seams for the refactoring lesson.
-    if (word === "add") {
+    // Operators are prefix forms: <word> <first> <connector> <second>.
+    const readBinaryOperation = (
+      connector: string,
+      combine: (first: number, second: number) => number,
+    ): number => {
       const first = read();
-      if (pieces[place++] !== "and") fail();
+      if (pieces[place++] !== connector) fail();
       const second = read();
-      return first + second;
-    }
-
-    if (word === "subtract") {
-      const first = read();
-      if (pieces[place++] !== "from") fail();
-      const second = read();
-      return second - first;
-    }
-
-    if (word === "multiply") {
-      const first = read();
-      if (pieces[place++] !== "by") fail();
-      const second = read();
-      return first * second;
-    }
+      return combine(first, second);
